/* Engine sound (ENG_SND): see engine_snd.h. Glue only: the generic parts are SH2ZAM snd-1. */
#include <yaul.h>
#include "engine_snd.h"
#include "texture_cd.h"
#include "sh2zam/snd_experimental.h"
#include "snd_race.h"      /* generated by tools/sfx_pack.py; git-ignored, local only */
#include "cdda_tracks.h"   /* generated by tools/disc_cdda.py; git-ignored, local only */

#ifndef ENG_SND_MUSIC
#define ENG_SND_MUSIC 0
#endif

#define SCSP_RAM ((volatile uint16_t *)0x25A00000u)
#define SCSP_SLOTS ((volatile uint16_t *)0x25B00000u)
#define SCSP_COMMON (*(volatile uint16_t *)0x25B00400u)
#define CD_REGS ((volatile uint16_t *)0x25890000u)
#define CD_DATA ((volatile const uint32_t *)0x25818000u)

/* Slot ranges (slots 16 and 17 carry the CD input level and stay unused). */
#define SLOTS_PLAYER 0u, 2u
#define SLOTS_RIVAL0 2u, 2u
#define SLOTS_RIVAL1 4u, 2u
#define SLOTS_ONE_SHOT 6u, 10u
#define SLOTS_VOICE 18u, 2u
#define LAP_SPEECH_PRIORITY 3u

volatile uint32_t engine_snd_report[16];

static sh2z_snd_t snd;
static sh2z_cdda_t cd;
static sh2z_snd_queue_t queue;
static uint32_t epoch_now;
static sh2z_snd_clip_t ev_clip[SND_RACE_EVENT_COUNT][SND_RACE_EVENT_PARTS];
static uint8_t ev_level[SND_RACE_EVENT_COUNT][SND_RACE_EVENT_PARTS];
static int8_t player_slot[SND_RACE_EVENT_PARTS], rival_slot[2][SND_RACE_EVENT_PARTS];
static uint32_t ticks;
#if E1_FIELD
static uint32_t last_cars_tick;
#endif
static int32_t prev_boost, prev_laps = -1;
static uint32_t prev_recoil;
static int32_t player_speed;
static struct { uint8_t level; int8_t pan; uint32_t ratio; } rival[2];
/* One frame's sound, built with the frame and released at its present. Two stages: the one the
 * build writes, and the one sealed with the frame VDP1 is drawing (engine_snd_seal). */
#define STAGE_EVENTS 16u
typedef struct {
    uint16_t ev[STAGE_EVENTS];
    uint32_t count;
    int8_t player_oct[SND_RACE_EVENT_PARTS]; uint16_t player_fns[SND_RACE_EVENT_PARTS];
    int8_t rival_oct[2][SND_RACE_EVENT_PARTS]; uint16_t rival_fns[2][SND_RACE_EVENT_PARTS];
    uint8_t rival_level[2][SND_RACE_EVENT_PARTS];
    uint8_t pitch_ok[3][SND_RACE_EVENT_PARTS];
} stage_t;
static stage_t stage[2];
static volatile uint32_t build_stage, sealed = 0xFFu;
#if E1_FIELD
static int32_t car_prev[FZX_FIELD_CARS + 1][3];
static uint8_t car_seen[FZX_FIELD_CARS + 1];
#endif

void engine_snd_power(void) {
    smpc_smc_sndoff_call();
    SCSP_RAM[0] = 0x0007u; SCSP_RAM[1] = 0xFFFCu;   /* 68000 reset vector: stack */
    SCSP_RAM[2] = 0x0000u; SCSP_RAM[3] = 0x0010u;   /* pc */
    SCSP_RAM[8] = 0x60FEu;                          /* bra.s to itself: the 68000 idles */
    smpc_smc_sndon_call();
    SCSP_COMMON = 0x0200u | 0x000Fu;                /* 4 Mbit sound RAM, master volume full */
    sh2z_snd_init(&snd, SCSP_SLOTS);
    sh2z_cdda_init(&cd, CD_REGS, SCSP_SLOTS);       /* after the slots: sets the CD input level */
    sh2z_snd_queue_init(&queue);
}

/* A one-shot's length in frames at the pitch it plays (OCT/FNS), rounded up. */
static uint16_t clip_frames(uint32_t samples, int8_t oct, uint16_t fns) {
    uint64_t num = (uint64_t)samples * 60u * 1024u, den = (uint64_t)44100u * (1024u + fns);
    if (oct < 0) num <<= -oct; else den <<= oct;
    const uint64_t f = (num + den - 1u) / den;
    return (uint16_t)(f > 0xFFFFu ? 0xFFFFu : f);
}

bool engine_snd_load(void *scratch, uint32_t scratch_bytes) {
    if (!fzx_texture_cd_load("SNDRACE.PAK", SND_RACE_PAK_BYTES, SND_RACE_PAK_HASH,
                             (void *)((uintptr_t)SCSP_RAM + SND_RACE_CLIPS_BASE), scratch, scratch_bytes)) {
        engine_snd_report[0] = 2u;
        return false;
    }
    for (unsigned e = 0; e < SND_RACE_EVENT_COUNT; ++e)
        for (unsigned p = 0; p < SND_RACE_EVENT_PARTS; ++p) {
            const snd_race_part_t *part = &snd_race_events[e][p];
            if (part->clip == 0xFFu) continue;
            const snd_race_clip_t *c = &snd_race_clips[part->clip];
            sh2z_snd_clip_t *k = &ev_clip[e][p];
            k->address = c->offset;
            k->loop_start = c->loop_start;
            k->loop_end = c->loop_end;
            k->oct = part->oct;
            k->fns = part->fns;
            k->tl = c->tl;
            k->loop = c->loop;
            k->pcm8 = 1u;
            k->frames = c->loop ? 0u : clip_frames(c->samples, part->oct, part->fns);
            ev_level[e][p] = part->level;
        }
    return true;
}

static void play_event(unsigned ev, uint32_t first, uint32_t count, uint8_t priority, int8_t *slots) {
    for (unsigned p = 0; p < SND_RACE_EVENT_PARTS; ++p) {
        if (snd_race_events[ev][p].clip == 0xFFu) continue;
        const int32_t s = sh2z_snd_play(&snd, &ev_clip[ev][p], first, count, priority, ev_level[ev][p], 0);
        if (slots) slots[p] = (int8_t)s;
    }
}

static void deliver(const sh2z_snd_event_t *e, void *ctx) {
    (void)ctx;
    switch (e->id) {
    case SND_RACE_EV_LAP_TWO:
    case SND_RACE_EV_LAP_FINAL:
        play_event(e->id, SLOTS_VOICE, LAP_SPEECH_PRIORITY, NULL);
        break;
    case SND_RACE_EV_BOOST:
    case SND_RACE_EV_WALL:
        play_event(e->id, SLOTS_ONE_SHOT, 2u, NULL);
        break;
    default:
        play_event(e->id, SLOTS_ONE_SHOT, 1u, NULL);
        break;
    }
}

static void post(uint16_t ev) {
    if (sh2z_snd_queue_post(&queue, ev, 0, epoch_now)) ++engine_snd_report[1];
}

static uint32_t read_toc(uint32_t *toc) {
    uint8_t status; uint16_t words;
    if (cd_block_cmd_cd_dev_connection_set(0xFFu)) return 0u;   /* audio sectors must not fill data buffers */
    if (cd_block_cmd_toc_get(&status, &words) || words < 204u) return 0u;
    uint16_t last = cpu_frt_count_get(); uint32_t elapsed = 0;
    while (!(CD_REGS[4] & 0x0002u)) {
        const uint16_t now = cpu_frt_count_get();
        elapsed += (uint16_t)(now - last); last = now;
        if (elapsed > 3000000u) return 0u;
    }
    for (unsigned i = 0; i < 102u; ++i) toc[i] = *CD_DATA;
    return cd_block_cmd_data_transfer_end() < 0 ? 0u : 1u;
}

void engine_snd_start(uint32_t epoch) {
    epoch_now = epoch;
    sh2z_snd_queue_open(&queue, epoch);
    const uint32_t mask = cpu_intc_mask_get();
    cpu_intc_mask_set(15);                          /* the VBlank-In plays on the same voices */
    play_event(SND_RACE_EV_ENGINE_PLAYER, SLOTS_PLAYER, 3u, player_slot);
    play_event(SND_RACE_EV_ENGINE_RIVAL, SLOTS_RIVAL0, 3u, rival_slot[0]);
    play_event(SND_RACE_EV_ENGINE_RIVAL, SLOTS_RIVAL1, 3u, rival_slot[1]);
    for (unsigned r = 0; r < 2u; ++r)
        for (unsigned p = 0; p < SND_RACE_EVENT_PARTS; ++p)
            if (rival_slot[r][p] >= 0 && snd_race_events[SND_RACE_EV_ENGINE_RIVAL][p].clip != 0xFFu)
                sh2z_snd_set_level(&snd, (uint32_t)rival_slot[r][p], 0u);
    cpu_intc_mask_set(mask);
    uint32_t toc[102];
    if (!read_toc(toc)) { engine_snd_report[0] = 3u; return; }
    for (unsigned i = 0; i < FZX_CDDA_TRACK_COUNT; ++i) {
        const fzx_cdda_track_t *t = &fzx_cdda_tracks[i];
        if (t->music_id != ENG_SND_MUSIC) continue;
        const uint32_t fad = sh2z_cdda_track_fad(toc, t->track);
        if (!fad) break;
        if (t->loop_sector == FZX_CDDA_NO_LOOP) sh2z_cdda_play(&cd, fad, t->sectors, 0u, 0u);
        else sh2z_cdda_play(&cd, fad, t->sectors, fad + t->loop_sector, t->sectors - t->loop_sector);
        engine_snd_report[0] = 1u;
        return;
    }
    engine_snd_report[0] = 4u;
}

void engine_snd_tick(const sh2z_vd_body_t *body, const sh2z_vd_vehicle_t *vehicle, int32_t laps) {
    ++ticks;
    player_speed = body->speed;
    if (body->boost_timer > 0 && prev_boost <= 0) { post(SND_RACE_EV_BOOST); ++engine_snd_report[13]; }
    prev_boost = body->boost_timer;
    const uint32_t recoil = body->flags & SH2Z_VD_RECOIL;
    if (recoil && !prev_recoil) { post(SND_RACE_EV_WALL); ++engine_snd_report[14]; }
    prev_recoil = recoil;
    if (prev_laps >= 0 && body->laps_done != prev_laps && !(body->flags & SH2Z_VD_FINISHED)) {
        const int32_t lap = body->laps_done + 1;                    /* the lap now being driven */
        if (lap == 2) { post(SND_RACE_EV_LAP_TWO); ++engine_snd_report[15]; }
        if (lap == laps) { post(SND_RACE_EV_LAP_FINAL); ++engine_snd_report[15]; }
    }
    prev_laps = body->laps_done;
    /* The low-energy beep: under 30 %, faster under 20 % and 10 % (racer.c), not while spinning. */
    if (vehicle->max_energy > 0 && body->spin_timer == 0 && !(body->flags & (SH2Z_VD_CRASHED | SH2Z_VD_FINISHED))) {
        const int64_t e10 = (int64_t)body->energy * 10;
        const int64_t m = vehicle->max_energy;
        if (e10 < 3 * m) {
            if (e10 >= 2 * m) { if (!(ticks & 0x1Fu)) post(SND_RACE_EV_ENERGY_SLOW); }
            else if (e10 >= m) { if (!(ticks & 0xFu)) post(SND_RACE_EV_ENERGY_MEDIUM); }
            else if (!(ticks & 7u)) post(SND_RACE_EV_ENERGY_FAST);
        }
    }
}

#if E1_FIELD
static uint32_t isqrt64(uint64_t v) {
    uint64_t r = 0, bit = (uint64_t)1 << 62;
    while (bit > v) bit >>= 2;
    while (bit) {
        if (v >= r + bit) { v -= r + bit; r = (r >> 1) + bit; } else r >>= 1;
        bit >>= 2;
    }
    return (uint32_t)r;
}

#endif

/* Engine pitch from speed as the game sets it (external.c): (speed + 0.01) / 21 + 0.25, as 16.16. */
static uint32_t engine_ratio(int32_t speed_q16) {
    const int32_t s = speed_q16 < 0 ? -speed_q16 : speed_q16;
    uint32_t r = (uint32_t)(s / 21) + 0x4000u + 31u;
    return r > 0x40000u ? 0x40000u : r;
}

#if E1_FIELD
void engine_snd_cars(const sh2z_vd_body_t *body, const fzx_field_car_t *cars, unsigned n) {
    const uint32_t dt = ticks - last_cars_tick;
    last_cars_tick = ticks;
    uint32_t best_d[2] = { 0xFFFFFFFFu, 0xFFFFFFFFu };
    int best[2] = { -1, -1 };
    for (unsigned i = 0; i < n; ++i) {
        const fzx_field_car_t *c = &cars[i];
        if (c->id == 0u || c->id > FZX_FIELD_CARS) continue;
        int64_t d2 = 0;
        for (unsigned k = 0; k < 3u; ++k) { const int64_t d = (int64_t)(c->pos[k] - body->pos[k]) >> 16; d2 += d * d; }
        const uint32_t d = isqrt64((uint64_t)d2);
        if (d < best_d[0]) { best_d[1] = best_d[0]; best[1] = best[0]; best_d[0] = d; best[0] = (int)i; }
        else if (d < best_d[1]) { best_d[1] = d; best[1] = (int)i; }
    }
    for (unsigned r = 0; r < 2u; ++r) {
        rival[r].level = 0u;
        engine_snd_report[11 + r] = best_d[r];
        if (best[r] < 0) continue;
        const fzx_field_car_t *c = &cars[best[r]];
        /* Level as the game's nearest-enemy rule: 1 - 9/190000 * distance, silent below 0.3, at most 0.85. */
        if (best_d[r] < 10000u) {
            const int32_t v = 255 - (int32_t)((best_d[r] * 9u * 255u) / 190000u);
            if (v > 77) rival[r].level = (uint8_t)(v > 217 ? 217 : v);
        }
        /* Pan from the car's offset along the player's left row (Q30). */
        int64_t lat = 0;
        for (unsigned k = 0; k < 3u; ++k) lat += ((int64_t)(c->pos[k] - body->pos[k]) >> 16) * (body->body[2][k] >> 14);
        lat >>= 16;
        int32_t pan = (int32_t)(-lat * 15 / 1500);
        rival[r].pan = (int8_t)(pan < -15 ? -15 : pan > 15 ? 15 : pan);
        /* Its speed from the distance it moved since the last frame. */
        int32_t speed = player_speed;
        if (car_seen[c->id] && dt) {
            int64_t m2 = 0;
            for (unsigned k = 0; k < 3u; ++k) { const int64_t d = (int64_t)(c->pos[k] - car_prev[c->id][k]) >> 8; m2 += d * d; }
            speed = (int32_t)(((uint64_t)isqrt64((uint64_t)m2) << 8) / dt);
        }
        rival[r].ratio = engine_ratio(speed);
    }
    for (unsigned i = 0; i < n; ++i) {
        const fzx_field_car_t *c = &cars[i];
        if (c->id > FZX_FIELD_CARS) continue;
        car_prev[c->id][0] = c->pos[0]; car_prev[c->id][1] = c->pos[1]; car_prev[c->id][2] = c->pos[2];
        car_seen[c->id] = 1u;
    }
}
#endif

static void collect(const sh2z_snd_event_t *e, void *ctx) {
    stage_t *st = ctx;
    if (st->count < STAGE_EVENTS) st->ev[st->count++] = e->id;
}

static void pitch_into(unsigned ev, uint32_t ratio, int8_t *oct, uint16_t *fns, uint8_t *ok) {
    for (unsigned p = 0; p < SND_RACE_EVENT_PARTS; ++p)
        ok[p] = snd_race_events[ev][p].clip != 0xFFu && sh2z_snd_pitch_scale(&ev_clip[ev][p], ratio, &oct[p], &fns[p]);
}

void engine_snd_build(void) {
    stage_t *st = &stage[build_stage];
    st->count = 0u;
    sh2z_snd_queue_drain(&queue, collect, st);
    pitch_into(SND_RACE_EV_ENGINE_PLAYER, engine_ratio(player_speed), st->player_oct, st->player_fns, st->pitch_ok[0]);
    for (unsigned r = 0; r < 2u; ++r) {
        pitch_into(SND_RACE_EV_ENGINE_RIVAL, rival[r].ratio ? rival[r].ratio : 0x4000u, st->rival_oct[r], st->rival_fns[r],
                   st->pitch_ok[1 + r]);
        for (unsigned p = 0; p < SND_RACE_EVENT_PARTS; ++p)
            st->rival_level[r][p] = (uint8_t)((rival[r].level * ev_level[SND_RACE_EV_ENGINE_RIVAL][p]) >> 8);
    }
    sh2z_cdda_frame(&cd);
    engine_snd_report[2] = queue.delivered; engine_snd_report[3] = queue.rejected;
    engine_snd_report[7] = cd.commands; engine_snd_report[8] = cd.loop_backs; engine_snd_report[9] = cd.state;
}

void engine_snd_seal(void) {
    sealed = build_stage;
    build_stage ^= 1u;
}

static void apply(const stage_t *st) {
    for (uint32_t i = 0; i < st->count; ++i) {
        sh2z_snd_event_t e; e.id = st->ev[i]; e.arg = 0; e.epoch = epoch_now;
        deliver(&e, NULL);
    }
    for (unsigned p = 0; p < SND_RACE_EVENT_PARTS; ++p) {
        if (st->pitch_ok[0][p] && player_slot[p] >= 0) {
            sh2z_snd_set_pitch(&snd, (uint32_t)player_slot[p], st->player_oct[p], st->player_fns[p]);
            if (p == 0u) engine_snd_report[10] = st->player_fns[p] | (uint32_t)(uint8_t)st->player_oct[p] << 16;
        }
        for (unsigned r = 0; r < 2u; ++r)
            if (rival_slot[r][p] >= 0 && snd_race_events[SND_RACE_EV_ENGINE_RIVAL][p].clip != 0xFFu) {
                if (st->pitch_ok[1 + r][p]) sh2z_snd_set_pitch(&snd, (uint32_t)rival_slot[r][p], st->rival_oct[r][p], st->rival_fns[r][p]);
                sh2z_snd_set_level(&snd, (uint32_t)rival_slot[r][p], st->rival_level[r][p]);
            }
    }
    engine_snd_report[4] = snd.plays; engine_snd_report[5] = snd.refused; engine_snd_report[6] = snd.stolen;
}

void engine_snd_vblank(bool presented) {
    if (presented && sealed < 2u) { apply(&stage[sealed]); sealed = 0xFFu; }
    sh2z_snd_frame(&snd);   /* one-shot lengths count fields */
}

void engine_snd_frame(void) {
    engine_snd_build();
    engine_snd_seal();
    apply(&stage[sealed]);
    sealed = 0xFFu;
    sh2z_snd_frame(&snd);
}

void engine_snd_leave(uint32_t frames) {
    const uint32_t mask = cpu_intc_mask_get();
    cpu_intc_mask_set(15);
    sealed = 0xFFu;
    stage[0].count = stage[1].count = 0u;
    sh2z_snd_queue_close(&queue);
    sh2z_cdda_fade(&cd, frames);
    for (uint32_t s = 0; s < SH2Z_SND_SLOTS; ++s) if (s != 16u && s != 17u) sh2z_snd_stop(&snd, s);
    for (unsigned p = 0; p < SND_RACE_EVENT_PARTS; ++p) { player_slot[p] = -1; rival_slot[0][p] = -1; rival_slot[1][p] = -1; }
    cpu_intc_mask_set(mask);
}

bool engine_snd_quiet(void) {
    return sh2z_cdda_quiet(&cd);
}
